-- Let's see how many wickets are attributed to a bowler by joining wicket_taken with ball_by_ball
SELECT COUNT(*) FROM wicket_taken w
JOIN ball_by_ball b ON w.match_id = b.match_id AND w.over_id = b.over_id AND w.ball_id = b.ball_id AND w.innings_no = b.innings_no;

-- Check what bowler values exist and if they're all in player table
SELECT COUNT(DISTINCT bowler) as distinct_bowlers FROM ball_by_ball;
SELECT COUNT(DISTINCT player_id) FROM player;
